import json,numpy as np
from scipy.optimize import least_squares
d=json.load(open('rand1.json'));u=np.array(d['u']);y=np.array(d['y'])
off=y[:,1]-0.5*u[:,0]-0.58*u[:,1]; mode=(off>-0.6).astype(float)
ticks=list(range(3,120,4))
def res(p,shift,usemode=False):
    a,b1,b2,c=p[:4]; bm=p[4] if usemode else 0
    out=[]
    for k in range(len(ticks)-1):
        t0,t1=ticks[k],ticks[k+1]
        x=y[t0,0]
        for t in range(t0+1-shift,t1+1-shift):
            x=a*x+b1*u[t,0]+b2*u[t,1]+c+bm*mode[t]
        out.append(x-y[t1,0])
    return np.array(out)
for sh in [0,1,2]:
    for um in [False,True]:
        p0=[0.8,0.1,-0.1,0]+([0] if um else [])
        r=least_squares(res,p0,args=(sh,um));print(sh,um,np.round(r.x,3),np.std(r.fun).round(3))
